From e07ff786a3c1c8752fa0d230c9a365523069a27a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:27:11 +0100
Subject: [PATCH] wallpapers/potd: don't cache a picture that was only partly
 downloaded

A cut off JPEG still decodes with its missing part in gray, so it was
cached as the day's picture. Now an incomplete or undecodable download
counts as failed: the previous picture stays and it is retried later.

BUG: 518488
---
 wallpapers/potd/plugins/potdengine.cpp                 |  5 +++++
 wallpapers/potd/plugins/potdprovider.cpp               | 10 ++++++++++
 wallpapers/potd/plugins/potdprovider.h                 |  8 ++++++++
 wallpapers/potd/plugins/providers/apodprovider.cpp     |  2 +-
 wallpapers/potd/plugins/providers/bingprovider.cpp     |  2 +-
 .../potd/plugins/providers/davidrevoyprovider.cpp      |  4 ++--
 wallpapers/potd/plugins/providers/flickrprovider.cpp   |  2 +-
 .../potd/plugins/providers/simonstalenhagprovider.cpp  |  2 +-
 wallpapers/potd/plugins/providers/wcpotdprovider.cpp   |  2 +-
 9 files changed, 30 insertions(+), 7 deletions(-)

diff --git a/wallpapers/potd/plugins/potdengine.cpp b/wallpapers/potd/plugins/potdengine.cpp
index 9e1dd82f9..89692e7fb 100644
--- a/wallpapers/potd/plugins/potdengine.cpp
+++ b/wallpapers/potd/plugins/potdengine.cpp
@@ -109,6 +109,11 @@ void PotdClient::setUpdateOverMeteredConnection(int value)

 void PotdClient::slotFinished(PotdProvider *provider, const QImage &image)
 {
+    if (image.isNull() && qobject_cast<CachedProvider *>(provider) == nullptr) {
+        slotError(provider);
+        return;
+    }
+
     setInfoUrl(provider->infoUrl());
     setRemoteUrl(provider->remoteUrl());
     setTitle(provider->title());
diff --git a/wallpapers/potd/plugins/potdprovider.cpp b/wallpapers/potd/plugins/potdprovider.cpp
index 1da287d07..c34273f22 100644
--- a/wallpapers/potd/plugins/potdprovider.cpp
+++ b/wallpapers/potd/plugins/potdprovider.cpp
@@ -91,3 +91,13 @@ QString PotdProvider::author() const
 {
     return m_author;
 }
+
+QImage PotdProvider::imageFromData(const QByteArray &data)
+{
+    // A cut off JPEG still decodes, with the missing part filled in gray, so
+    // check that the last scan is followed by the end of image marker
+    if (data.startsWith("\xFF\xD8") && data.lastIndexOf("\xFF\xD9") < data.lastIndexOf("\xFF\xDA")) {
+        return QImage();
+    }
+    return QImage::fromData(data);
+}
diff --git a/wallpapers/potd/plugins/potdprovider.h b/wallpapers/potd/plugins/potdprovider.h
index 1ddb12a8a..dbe838020 100644
--- a/wallpapers/potd/plugins/potdprovider.h
+++ b/wallpapers/potd/plugins/potdprovider.h
@@ -108,6 +108,14 @@ Q_SIGNALS:
     void error(PotdProvider *provider);

 protected:
+    /**
+     * Decodes downloaded image data.
+     *
+     * @return the image, or a null image if the data is incomplete
+     * @since 6.9
+     */
+    static QImage imageFromData(const QByteArray &data);
+
     QUrl m_remoteUrl;
     QUrl m_infoUrl;
     QString m_title;
diff --git a/wallpapers/potd/plugins/providers/apodprovider.cpp b/wallpapers/potd/plugins/providers/apodprovider.cpp
index 26fa36146..d2a58d063 100644
--- a/wallpapers/potd/plugins/providers/apodprovider.cpp
+++ b/wallpapers/potd/plugins/providers/apodprovider.cpp
@@ -70,7 +70,7 @@ void ApodProvider::imageRequestFinished(KJob *_job)
         return;
     }

-    Q_EMIT finished(this, QImage::fromData(job->data()));
+    Q_EMIT finished(this, imageFromData(job->data()));
 }

 K_PLUGIN_CLASS_WITH_JSON(ApodProvider, "apodprovider.json")
diff --git a/wallpapers/potd/plugins/providers/bingprovider.cpp b/wallpapers/potd/plugins/providers/bingprovider.cpp
index 25573086f..b90437e12 100644
--- a/wallpapers/potd/plugins/providers/bingprovider.cpp
+++ b/wallpapers/potd/plugins/providers/bingprovider.cpp
@@ -103,7 +103,7 @@ void BingProvider::imageRequestFinished(KJob *_job)
         return;
     }
     QByteArray data = job->data();
-    Q_EMIT finished(this, QImage::fromData(data));
+    Q_EMIT finished(this, imageFromData(data));
 }

 K_PLUGIN_CLASS_WITH_JSON(BingProvider, "bingprovider.json")
diff --git a/wallpapers/potd/plugins/providers/davidrevoyprovider.cpp b/wallpapers/potd/plugins/providers/davidrevoyprovider.cpp
index d649853eb..6613c1d71 100644
--- a/wallpapers/potd/plugins/providers/davidrevoyprovider.cpp
+++ b/wallpapers/potd/plugins/providers/davidrevoyprovider.cpp
@@ -97,7 +97,7 @@ void DavidRevoyProvider::imageRequestFinished(KJob *_job)
     m_imageData = job->data();

     if (m_checksum.isEmpty()) {
-        Q_EMIT finished(this, QImage::fromData(m_imageData));
+        Q_EMIT finished(this, imageFromData(m_imageData));
         return;
     }

@@ -116,7 +116,7 @@ void DavidRevoyProvider::checksumCalculationFinished(KJob *job)
         return;
     }

-    Q_EMIT finished(this, QImage::fromData(m_imageData));
+    Q_EMIT finished(this, imageFromData(m_imageData));
 }

 ChecksumJob::ChecksumJob(const QByteArray &data, QObject *parent)
diff --git a/wallpapers/potd/plugins/providers/flickrprovider.cpp b/wallpapers/potd/plugins/providers/flickrprovider.cpp
index 994920e3f..89d0b9130 100644
--- a/wallpapers/potd/plugins/providers/flickrprovider.cpp
+++ b/wallpapers/potd/plugins/providers/flickrprovider.cpp
@@ -229,7 +229,7 @@ void FlickrProvider::imageRequestFinished(KJob *_job)
         return;
     }

-    m_image = QImage::fromData(job->data());
+    m_image = imageFromData(job->data());

     // Visit the photo page to get the author
     if (!m_infoUrl.isEmpty()) {
diff --git a/wallpapers/potd/plugins/providers/simonstalenhagprovider.cpp b/wallpapers/potd/plugins/providers/simonstalenhagprovider.cpp
index 8ea92d64a..c1bac36c9 100644
--- a/wallpapers/potd/plugins/providers/simonstalenhagprovider.cpp
+++ b/wallpapers/potd/plugins/providers/simonstalenhagprovider.cpp
@@ -129,7 +129,7 @@ void SimonStalenhagProvider::imageRequestFinished(KJob *_job)
         return;
     }
     QByteArray data = job->data();
-    Q_EMIT finished(this, QImage::fromData(data));
+    Q_EMIT finished(this, imageFromData(data));
 }

 K_PLUGIN_CLASS_WITH_JSON(SimonStalenhagProvider, "simonstalenhagprovider.json")
diff --git a/wallpapers/potd/plugins/providers/wcpotdprovider.cpp b/wallpapers/potd/plugins/providers/wcpotdprovider.cpp
index 2e8f31830..d901c0fe7 100644
--- a/wallpapers/potd/plugins/providers/wcpotdprovider.cpp
+++ b/wallpapers/potd/plugins/providers/wcpotdprovider.cpp
